import static org.junit.Assert.*;

public class Complex_divide_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDivide_NullArgument() {
        Complex z = new Complex(1.0, 1.0);
        try {
            z.divide(null);
            fail("Expected NullArgumentException");
        } catch (NullArgumentException e) {
            // Success
        }
    }

    @Test
    public void testDivide_NaN_Result() {
        Complex nan = Complex.NaN;
        Complex z = new Complex(1.0, 1.0);

        // If dividend is NaN
        assertTrue(nan.divide(z).isNaN());

        // If divisor is NaN
        assertTrue(z.divide(nan).isNaN());
    }

    @Test
    public void testDivide_DivisorIsZero() {
        Complex z = new Complex(1.0, 1.0);
        Complex zero = new Complex(0.0, 0.0);

        Complex result = z.divide(zero);
        assertTrue("Division by zero should return NaN per implementation", result.isNaN());
    }

    @Test
    public void testDivide_DivisorIsInfinite_DividendIsFinite() {
        Complex z = new Complex(1.0, 1.0);
        Complex inf = new Complex(Double.POSITIVE_INFINITY, 0.0);

        Complex result = z.divide(inf);
        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_DivisorIsInfinite_DividendIsInfinite() {
        Complex inf = new Complex(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY);

        // If both are infinite, it follows the logic flow after the isInfinite checks
        // The current code doesn't explicitly return NaN for Inf/Inf, it proceeds to math
        // But based on the code provided, the isInfinite() check only triggers if !isInfinite()
        Complex result = inf.divide(inf);
        // Depending on math, result might be NaN or a complex value. 
        // We test the branch coverage.
        assertNotNull(result);
    }

    @Test
    public void testDivide_Branch_AbsC_LessThan_AbsD() {
        // Case: abs(c) < abs(d)
        // divisor.getReal() = 1.0, divisor.getImaginary() = 2.0
        // c = 1, d = 2. |1| < |2| is true.
        Complex z = new Complex(4.0, 2.0);
        Complex divisor = new Complex(1.0, 2.0);

        // (4 + 2i) / (1 + 2i) = [(4+2i)(1-2i)] / [1^2 + 2^2]
        // = [4 - 8i + 2i - 4i^2] / 5 = [4 + 4 - 6i] / 5 = 8/5 - 6/5i = 1.6 - 1.2i
        Complex result = z.divide(divisor);

        assertEquals(1.6, result.getReal(), EPSILON);
        assertEquals(-1.2, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_Branch_AbsC_GreaterThanOrEqual_AbsD() {
        // Case: abs(c) >= abs(d)
        // divisor.getReal() = 2.0, divisor.getImaginary() = 1.0
        // c = 2, d = 1. |2| < |1| is false.
        Complex z = new Complex(4.0, 2.0);
        Complex divisor = new Complex(2.0, 1.0);

        // (4 + 2i) / (2 + 1i) = [(4+2i)(2-i)] / [2^2 + 1^2]
        // = [8 - 4i + 4i - 2i^2] / 5 = [8 + 2] / 5 = 2.0 + 0.0i
        Complex result = z.divide(divisor);

        assertEquals(2.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_EqualityAndHashCode() {
        Complex z1 = new Complex(1.0, 1.0);
        Complex z2 = new Complex(1.0, 1.0);
        Complex z3 = new Complex(1.0, 2.0);

        assertEquals(z1, z2);
        assertNotEquals(z1, z3);
        assertEquals(z1.hashCode(), z2.hashCode());
    }
}
